<?php
namespace Modules\Ran\Http\Controllers;use Modules\Ran\Entities\{Item,Purchase};use Modules\Ran\Http\Requests\PurchaseRequest;use Modules\Ran\Integrations\SupplierIntegrationService;use Modules\Ran\Services\PurchaseService;
class PurchaseController extends RanController{public function __construct(private PurchaseService $service,private SupplierIntegrationService $suppliers){}public function index(){return view('ran::purchases.index',['purchases'=>Purchase::query()->with('supplier')->latest('purchase_date')->latest('id')->paginate(25)]);}public function create(){return view('ran::purchases.form',array_merge($this->pageOptions(),['suppliers'=>$this->suppliers->dropdown(),'items'=>Item::query()->where('is_active',1)->orderBy('name')->pluck('name','id')]));}public function store(PurchaseRequest $r){$p=$this->service->create($r->validated());return $this->success('Purchase saved.','ran.purchases.show',[$p]);}public function show(Purchase $purchase){return view('ran::purchases.show',['purchase'=>$purchase->load('lines.item','supplier','payments')]);}public function post(Purchase $purchase){$this->service->post($purchase);return back()->with('status','Purchase posted to stock, supplier ledger and Finance.');}}
